export const rulesHtml = "<h2>Draft Rules</h2><ol><li>Every team must draft exactly 10 pokemon.</li><li>The points of those 10 pokemon added up must be \u2264105.</li><li>Draft order can be found in the teams sheet in the official documentation. The order will be snake style (1-8, 8-1, etc.) until all 10 are chosen.</li><li>Swapping out your team members is viable up to 8 times and will not be permitted starting week 3 of the draft.</li><li>Swaps may only occur if you have the available points. Remaining points and dropped pokemon points can be used to draft another pokemon.</li><li>When swapping, it is on a first come first serve basis. Any team changes will have to go through Joe unless you are directed to Michael.</li><li>Trades are allowed through the entirety of the draft but will also fall within the point limit. Please contact Joe for draft changes.</li><li>Scheduling falls on each team. Please reach out every week to schedule battles.</li><li>Weeks start on a Monday and end on a Sunday. Please ensure your battle is completed by Sunday each week.</li><li>A schedule chat has been added to the Draft Discord Server for those that don&#x27;t have each others number.</li><li>Battles will be best 2/3. If battles are going on too long, please confirm with the opponent on using the showdown battle timer.</li><li>6 of the 10 pokemon will be brought to each battle. These can vary every week until the final.</li><li>The 6 pokemon brought to each week cannot be changed within the best 2/3.</li><li>Only 1 item is allowed per pokemon. You cannot run 4 leftovers.</li><li>Any disconnects will be brought to Joe as each decision will be per instance.</li><li>Any incorrect teras will be brought to Joe to determine if it affected the battle. May result in a rematch.</li><li>Draft rooms are made for team prep with others, an hour or two per week of prep is suggested.</li><li>All battles are to be uploaded to the Draft document and in the replay chat on Discord.</li></ol><h2>Banned Abilities, Items & Moves</h2><ul><li>Ability: Arena Trap</li><li>Ability: Moody</li><li>Ability: Shadow Tag</li><li>Item: King&#x27;s Rock</li><li>Item: Quick Claw</li><li>Item: Razor Fang</li><li>Move: Baton Pass</li></ul>";
